export const NEW_TAB_MARKER = '---new tab---';
export const APPEND_MARKER = '---append here---';
export const PREPEND_MARKER = '---prepend here---';
export const LINE_PROMPT_MODE_MARKER = '---line prompt mode---';

export function resolveSeparator(raw) {
  if (!raw || typeof raw !== 'string') return PROMPT_SEPARATOR;
  // Support literal "\n" sequences entered by the user.
  return raw.replace(/\\n/g, '\n');
}

function normalizeNewlines(value) {
  if (typeof value !== 'string') return '';
  return value.replace(/\r\n/g, '\n');
}

function isNewTabMarker(value) {
  if (typeof value !== 'string') return false;
  const trimmed = value.trim().toLowerCase();
  // Match dash format variations like ---new tab---, ----new tab----, etc.
  return /^-+new\s+tab-+$/.test(trimmed);
}

function isAppendMarker(value) {
  if (typeof value !== 'string') return false;
  const trimmed = value.trim().toLowerCase();
  // Match dash format variations like ---append here---, ----append here----, etc.
  return /^-+append\s+here-+$/.test(trimmed);
}

function isPrependMarker(value) {
  if (typeof value !== 'string') return false;
  const trimmed = value.trim().toLowerCase();
  // Match dash format variations like ---prepend here---, ----prepend here----, etc.
  return /^-+prepend\s+here-+$/.test(trimmed);
}

function isLinePromptModeMarker(value) {
  if (typeof value !== 'string') return false;
  const trimmed = value.trim().toLowerCase();
  // Match dash format variations like ---line prompt mode---, ----line prompt mode----, etc.
  return /^-+line\s+prompt\s+mode-+$/.test(trimmed);
}

function isDividerLine(value) {
  if (typeof value !== 'string') return false;
  return /^-{3,}$/.test(value.trim());
}

function isInlineNextPromptSeparatorLine(value) {
  if (typeof value !== 'string') return false;
  return /^-+next\s+prompt-+$/.test(value.trim().toLowerCase());
}

function appendToPrompt(text, appendText) {
  const base = typeof text === 'string' ? text.trim() : '';
  const append = typeof appendText === 'string' ? appendText.trim() : '';
  if (!append) return base;
  if (!base) return append;
  return `${base}\n\n${append}`;
}

function prependToPrompt(text, prependText) {
  const base = typeof text === 'string' ? text.trim() : '';
  const prepend = typeof prependText === 'string' ? prependText.trim() : '';
  if (!prepend) return base;
  if (!base) return prepend;
  return `${prepend}\n\n${base}`;
}

function buildParallelPromptGroupsFromTaggedPrompts(promptsWithMarkers) {
  const groups = [];
  let currentGroup = [];
  for (const prompt of promptsWithMarkers) {
    if (isNewTabMarker(prompt)) {
      if (currentGroup.length > 0) {
        groups.push(currentGroup);
      }
      currentGroup = [];
      continue;
    }
    currentGroup.push(prompt);
  }
  if (currentGroup.length > 0) {
    groups.push(currentGroup);
  }
  return groups;
}

function hasExplicitLinePromptMode(rawText, parsedPrompts) {
  if (typeof rawText === 'string' && rawText.trim()) {
    const lines = normalizeNewlines(rawText).split('\n');
    if (lines.some((line) => isLinePromptModeMarker(line))) {
      return true;
    }
  }
  return parsedPrompts.some((prompt) => isLinePromptModeMarker(prompt));
}

function expandPromptsForLinePromptMode(parsedPrompts) {
  const expanded = [];
  for (const prompt of parsedPrompts) {
    const normalizedPrompt = normalizeNewlines(prompt);
    const lines = normalizedPrompt.split('\n');
    for (const line of lines) {
      const candidate = line.trim();
      if (!candidate) continue;
      if (isDividerLine(candidate)) continue;
      if (isInlineNextPromptSeparatorLine(candidate)) continue;
      expanded.push(candidate);
    }
  }
  return expanded;
}

function getLastPromptItem(processedPrompts) {
  for (let i = processedPrompts.length - 1; i >= 0; i -= 1) {
    const item = processedPrompts[i];
    if (item?.type === 'prompt') {
      return item;
    }
    if (item?.type === 'marker' && item.marker === 'tab') {
      return null;
    }
  }
  return null;
}

export function buildPromptLaunchPlan(
  rawText,
  separatorRaw,
  appendText = '',
  prependText = '',
) {
  const separator = resolveSeparator(separatorRaw);
  const normalizedRawText = normalizeNewlines(typeof rawText === 'string' ? rawText : '');
  const normalizedSeparator = normalizeNewlines(separator);
  const parsedPrompts = parsePrompts(normalizedRawText, normalizedSeparator);
  const linePromptModeEnabled = hasExplicitLinePromptMode(normalizedRawText, parsedPrompts);
  const promptCandidates = linePromptModeEnabled
    ? expandPromptsForLinePromptMode(parsedPrompts)
    : parsedPrompts
      .map((prompt) => normalizeNewlines(prompt).trim())
      .filter((prompt) => prompt.length > 0);

  const effectiveAppendText = typeof appendText === 'string' ? appendText.trim() : '';
  const effectivePrependText = typeof prependText === 'string' ? prependText.trim() : '';
  // Marker semantics are independent from global prepend/append toggles:
  // markers should still work even when the global checkboxes are off.
  const canUseAppendMarker = effectiveAppendText.length > 0;
  const canUsePrependMarker = effectivePrependText.length > 0;

  const processedPrompts = [];
  let pendingAppendToNextPrompt = false;
  let pendingPrependToNextPrompt = false;
  let hasTabMarkers = false;
  let hasAppendMarkers = false;
  let hasPrependMarkers = false;

  for (const prompt of promptCandidates) {
    if (isLinePromptModeMarker(prompt)) {
      continue;
    }

    if (isNewTabMarker(prompt)) {
      hasTabMarkers = true;
      pendingAppendToNextPrompt = false;
      pendingPrependToNextPrompt = false;
      processedPrompts.push({ type: 'marker', marker: 'tab', original: prompt });
      continue;
    }

    if (isAppendMarker(prompt)) {
      hasAppendMarkers = true;
      if (canUseAppendMarker) {
        const lastPromptItem = getLastPromptItem(processedPrompts);
        if (lastPromptItem) {
          lastPromptItem.text = appendToPrompt(lastPromptItem.text, effectiveAppendText);
        } else {
          pendingAppendToNextPrompt = true;
        }
      }
      continue;
    }

    if (isPrependMarker(prompt)) {
      hasPrependMarkers = true;
      if (canUsePrependMarker) {
        const lastPromptItem = getLastPromptItem(processedPrompts);
        if (lastPromptItem) {
          lastPromptItem.text = prependToPrompt(lastPromptItem.text, effectivePrependText);
        } else {
          pendingPrependToNextPrompt = true;
        }
      }
      continue;
    }

    let promptText = prompt;
    if (pendingPrependToNextPrompt && canUsePrependMarker) {
      promptText = prependToPrompt(promptText, effectivePrependText);
      pendingPrependToNextPrompt = false;
    }
    if (pendingAppendToNextPrompt && canUseAppendMarker) {
      promptText = appendToPrompt(promptText, effectiveAppendText);
      pendingAppendToNextPrompt = false;
    }
    processedPrompts.push({ type: 'prompt', text: promptText, original: prompt });
  }

  const promptTexts = processedPrompts
    .filter((item) => item.type === 'prompt')
    .map((item) => item.text);
  const duplicateAdjusted = applyTypoVariantsToExactDuplicates(promptTexts);

  const promptsWithMarkers = [];
  const prompts = [];
  let adjustedIndex = 0;
  for (const item of processedPrompts) {
    if (item.type === 'marker' && item.marker === 'tab') {
      promptsWithMarkers.push(NEW_TAB_MARKER);
      continue;
    }
    const adjustedText = duplicateAdjusted.prompts[adjustedIndex] || item.text;
    promptsWithMarkers.push(adjustedText);
    prompts.push(adjustedText);
    adjustedIndex += 1;
  }

  const tabPromptGroups = hasTabMarkers
    ? buildParallelPromptGroupsFromTaggedPrompts(promptsWithMarkers)
    : prompts.map((prompt) => [prompt]);

  return {
    separator,
    prompts,
    promptsWithMarkers,
    tabPromptGroups,
    hasTabMarkers,
    hasAppendMarkers,
    hasPrependMarkers,
    linePromptModeEnabled,
    duplicateChanged: duplicateAdjusted.changed,
  };
}

import { applyConsolePatch, setDebugLoggingEnabled } from './popup-console-patch.js';
import { msToSec, secToMs, applyTheme } from './popup-dom-utils.js';

// Initialization and helpers for settings UI
export async function loadSettingsIntoUI() {
  try {
    const res = await chrome.runtime.sendMessage({ type: 'GET_SETTINGS' });
    if (res?.ok && res.settings) {
      const s = res.settings;
      applyTheme(s.theme || 'dark');
      document.getElementById('maxWaitSec').value = msToSec(s.maxWaitMs);
      document.getElementById('stableMinSec').value = msToSec(s.stableMinMs ?? s.stableMs);
      document.getElementById('stableMaxSec').value = msToSec(s.stableMaxMs ?? s.stableMs);
      document.getElementById('pollSec').value = msToSec(s.pollIntervalMs);
      document.getElementById('enableRetryOnFailure').checked = s.enableRetryOnFailure !== false;
      document.getElementById('maxRetriesPerPrompt').value = Number.isFinite(Number(s.maxRetriesPerPrompt)) ? Number(s.maxRetriesPerPrompt) : 2;
      document.getElementById('retryDelaySec').value = msToSec(s.retryDelayMs);
      document.getElementById('systemPrompt').value = s.systemPrompt || '';
      document.getElementById('appendPromptText').value = s.appendPromptText || '';
      document.getElementById('prependSystemPrompt').checked = s.prependSystemPrompt !== false;
      document.getElementById('appendSystemPrompt').checked = s.appendSystemPrompt === true;
      document.getElementById('enableMaxWaitTimeout').checked = s.enableMaxWaitTimeout !== false;
      document.getElementById('autoConfirmDialogs').checked = s.autoConfirmDialogs === true;
      document.getElementById('enableWatchedElementGate').checked = s.enableWatchedElementGate === true;
      document.getElementById('watchedElementSelector').value = s.watchedElementSelector || '';
      document.getElementById('enableStopWord').checked = s.enableStopWord === true;
      document.getElementById('stopWord').value = s.stopWord || '';
      document.getElementById('stopWordCaseSensitive').checked = s.stopWordCaseSensitive === true;
      document.getElementById('refreshTabBeforeEachPrompt').checked = s.refreshTabBeforeEachPrompt === true;
      const parallelOneTabPerPrompt = document.getElementById('parallelOneTabPerPrompt');
      if (parallelOneTabPerPrompt) {
        parallelOneTabPerPrompt.checked = s.parallelOneTabPerPrompt === true;
      }
      document.getElementById('debugLoggingEnabled').checked = s.debugLoggingEnabled === true;
      document.getElementById('openNewChatPerPrompt').checked = s.openNewChatPerPrompt === true;
      document.getElementById('openNewChatPerPromptUrl').value = s.openNewChatPerPromptUrl || '';
      setDebugLoggingEnabled(s.debugLoggingEnabled === true);

      const stopWordContainer = document.getElementById('stopWordContainer');
      const watchedElementContainer = document.getElementById('watchedElementContainer');
      if (s.enableStopWord === true) {
        stopWordContainer.classList.remove('hidden');
      } else {
        stopWordContainer.classList.add('hidden');
      }
      if (s.enableWatchedElementGate === true) {
        watchedElementContainer.classList.remove('hidden');
      } else {
        watchedElementContainer.classList.add('hidden');
      }
    }
  } catch (e) {
    console.error('[LoadSettings] Error:', e);
  }
}

export async function saveSettingsFromUI() {
  let settings = null;
  try {
    const maxWaitSec = Number(document.getElementById('maxWaitSec').value);
    const stableMinSec = Number(document.getElementById('stableMinSec').value);
    const stableMaxSec = Number(document.getElementById('stableMaxSec').value);
    const stableMinOrdered = Math.min(stableMinSec, stableMaxSec || stableMinSec);
    const stableMaxOrdered = Math.max(stableMinSec || stableMaxSec, stableMaxSec || stableMinSec);
    const pollSec = Number(document.getElementById('pollSec').value);
    settings = {
      maxWaitMs: secToMs(maxWaitSec),
      stableMinMs: secToMs(stableMinOrdered),
      stableMaxMs: secToMs(stableMaxOrdered),
      pollIntervalMs: secToMs(pollSec),
      enableRetryOnFailure: document.getElementById('enableRetryOnFailure').checked,
      maxRetriesPerPrompt: Number(document.getElementById('maxRetriesPerPrompt').value),
      retryDelayMs: secToMs(Number(document.getElementById('retryDelaySec').value)),
      systemPrompt: document.getElementById('systemPrompt').value || '',
      appendPromptText: document.getElementById('appendPromptText').value || '',
      prependSystemPrompt: document.getElementById('prependSystemPrompt').checked,
      appendSystemPrompt: document.getElementById('appendSystemPrompt').checked,
      enableMaxWaitTimeout: document.getElementById('enableMaxWaitTimeout').checked,
      autoConfirmDialogs: document.getElementById('autoConfirmDialogs').checked,
      enableWatchedElementGate: document.getElementById('enableWatchedElementGate').checked,
      watchedElementSelector: (document.getElementById('watchedElementSelector').value || '').trim(),
      enableStopWord: document.getElementById('enableStopWord').checked,
      stopWord: document.getElementById('stopWord').value || '',
      stopWordCaseSensitive: document.getElementById('stopWordCaseSensitive').checked,
      refreshTabBeforeEachPrompt: document.getElementById('refreshTabBeforeEachPrompt').checked,
      parallelOneTabPerPrompt: document.getElementById('parallelOneTabPerPrompt')?.checked === true,
      debugLoggingEnabled: document.getElementById('debugLoggingEnabled').checked,
      openNewChatPerPrompt: document.getElementById('openNewChatPerPrompt').checked,
      openNewChatPerPromptUrl: (document.getElementById('openNewChatPerPromptUrl').value || '').trim(),
    };
    await chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', settings });
    return settings;
  } catch (e) {
    console.error('[SaveSettings] Error:', e);
    return settings;
  }
}

export function initSettingsUI() {
  applyConsolePatch(undefined, false);

  const themeSelect = document.getElementById('themeSelect');
  if (themeSelect) {
    themeSelect.addEventListener('change', async (e) => {
      const val = e.target.value;
      applyTheme(val);
      try {
        await chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', settings: { theme: val } });
      } catch (err) {
        console.error('[ThemeChange] Error:', err);
      }
    });
  }

  ['maxWaitSec', 'stableMinSec', 'stableMaxSec', 'pollSec', 'enableRetryOnFailure', 'maxRetriesPerPrompt', 'retryDelaySec', 'systemPrompt', 'appendPromptText', 'prependSystemPrompt', 'appendSystemPrompt', 'enableMaxWaitTimeout', 'autoConfirmDialogs', 'enableWatchedElementGate', 'watchedElementSelector', 'refreshTabBeforeEachPrompt', 'parallelOneTabPerPrompt'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', saveSettingsFromUI);
  });

  const enableMaxWaitTimeoutCheckbox = document.getElementById('enableMaxWaitTimeout');
  if (enableMaxWaitTimeoutCheckbox) {
    enableMaxWaitTimeoutCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  const enableStopWordCheckbox = document.getElementById('enableStopWord');
  const stopWordContainer = document.getElementById('stopWordContainer');
  const stopWordInput = document.getElementById('stopWord');
  const stopWordCaseSensitiveCheckbox = document.getElementById('stopWordCaseSensitive');
  const enableWatchedElementGateCheckbox = document.getElementById('enableWatchedElementGate');
  const watchedElementContainer = document.getElementById('watchedElementContainer');
  const watchedElementSelectorInput = document.getElementById('watchedElementSelector');
  const useChatgptActionSelectorBtn = document.getElementById('useChatgptActionSelector');
  const debugLoggingEnabledCheckbox = document.getElementById('debugLoggingEnabled');
  const openNewChatPerPromptCheckbox = document.getElementById('openNewChatPerPrompt');
  const openNewChatPerPromptUrlInput = document.getElementById('openNewChatPerPromptUrl');

  if (enableStopWordCheckbox) {
    enableStopWordCheckbox.addEventListener('change', () => {
      if (enableStopWordCheckbox.checked) {
        stopWordContainer.classList.remove('hidden');
        stopWordInput.focus();
      } else {
        stopWordContainer.classList.add('hidden');
      }
      saveSettingsFromUI();
    });
  }

  if (stopWordInput) {
    stopWordInput.addEventListener('input', saveSettingsFromUI);
  }

  if (stopWordCaseSensitiveCheckbox) {
    stopWordCaseSensitiveCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  if (enableWatchedElementGateCheckbox) {
    enableWatchedElementGateCheckbox.addEventListener('change', () => {
      if (enableWatchedElementGateCheckbox.checked) {
        watchedElementContainer.classList.remove('hidden');
        watchedElementSelectorInput.focus();
      } else {
        watchedElementContainer.classList.add('hidden');
      }
      saveSettingsFromUI();
    });
  }

  if (watchedElementSelectorInput) {
    watchedElementSelectorInput.addEventListener('input', saveSettingsFromUI);
  }

  if (useChatgptActionSelectorBtn) {
    useChatgptActionSelectorBtn.addEventListener('click', () => {
      watchedElementSelectorInput.value = 'button[data-testid="copy-turn-action-button"]';
      if (enableWatchedElementGateCheckbox && !enableWatchedElementGateCheckbox.checked) {
        enableWatchedElementGateCheckbox.checked = true;
        watchedElementContainer.classList.remove('hidden');
      }
      saveSettingsFromUI();
    });
  }

  if (debugLoggingEnabledCheckbox) {
    debugLoggingEnabledCheckbox.addEventListener('change', () => {
      setDebugLoggingEnabled(debugLoggingEnabledCheckbox.checked);
      saveSettingsFromUI();
    });
  }

  if (openNewChatPerPromptCheckbox) {
    openNewChatPerPromptCheckbox.addEventListener('change', saveSettingsFromUI);
  }

  if (openNewChatPerPromptUrlInput) {
    openNewChatPerPromptUrlInput.addEventListener('change', saveSettingsFromUI);
    openNewChatPerPromptUrlInput.addEventListener('blur', saveSettingsFromUI);
  }
}

import { applyConsolePatch } from './popup-console-patch.js';
import { setStatus, setProgress, showToast, showError, hideError, clearError, setButtonsDisabled, secToMs } from './popup-dom-utils.js';
import { loadSettingsIntoUI, saveSettingsFromUI, initSettingsUI } from './popup-settings.js';
import { loadHistoryIntoUI, importHistoryItems, clearHistory, exportHistory, saveHistoryItem } from './popup-history.js';
import { NEW_TAB_MARKER, resolveSeparator, buildPromptLaunchPlan } from './popup-prompt-plan.js';

applyConsolePatch();

const separatorInput = document.getElementById('separatorInput');
let latestAutomationStatus = null;

async function getActiveTabId() {
  const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
  return tabs?.[0]?.id;
}

const pauseBtn = document.getElementById('pauseBtn');
const resumeBtn = document.getElementById('resumeBtn');
const parallelWalkthrough = document.getElementById('parallelWalkthrough');
const toggleParallelWalkthroughBtn = document.getElementById('toggleParallelWalkthroughBtn');
const PARALLEL_WALKTHROUGH_VISIBILITY_KEY = 'parallelWalkthroughVisible';

function setParallelWalkthroughVisibility(visible) {
  if (!parallelWalkthrough || !toggleParallelWalkthroughBtn) return;
  parallelWalkthrough.hidden = !visible;
  toggleParallelWalkthroughBtn.textContent = visible ? 'Hide guide' : 'Show guide';
}

function closeOpenInfoPopovers(exceptWrap = null) {
  document.querySelectorAll('.info-wrap.is-open').forEach((wrap) => {
    if (exceptWrap && wrap === exceptWrap) return;
    wrap.classList.remove('is-open');
    const btn = wrap.querySelector('.info-trigger');
    if (btn) btn.setAttribute('aria-expanded', 'false');
  });
}

function initInfoPopovers() {
  const infoButtons = document.querySelectorAll('.info-trigger');
  infoButtons.forEach((btn) => {
    btn.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      const wrap = btn.closest('.info-wrap');
      if (!wrap) return;
      const willOpen = !wrap.classList.contains('is-open');
      closeOpenInfoPopovers(wrap);
      wrap.classList.toggle('is-open', willOpen);
      btn.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
    });
  });

  document.addEventListener('click', () => closeOpenInfoPopovers());
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      closeOpenInfoPopovers();
    }
  });
}

async function loadParallelWalkthroughVisibility() {
  if (!parallelWalkthrough || !toggleParallelWalkthroughBtn) return;
  let visible = true;
  try {
    const result = await chrome.storage.local.get([PARALLEL_WALKTHROUGH_VISIBILITY_KEY]);
    if (typeof result?.[PARALLEL_WALKTHROUGH_VISIBILITY_KEY] === 'boolean') {
      visible = result[PARALLEL_WALKTHROUGH_VISIBILITY_KEY];
    }
  } catch (e) {
    console.error('[ParallelWalkthrough] Failed to load visibility:', e);
  }
  setParallelWalkthroughVisibility(visible);
}

if (toggleParallelWalkthroughBtn && parallelWalkthrough) {
  toggleParallelWalkthroughBtn.addEventListener('click', async () => {
    const currentlyVisible = !parallelWalkthrough.hidden;
    const nextVisible = !currentlyVisible;
    setParallelWalkthroughVisibility(nextVisible);
    try {
      await chrome.storage.local.set({ [PARALLEL_WALKTHROUGH_VISIBILITY_KEY]: nextVisible });
    } catch (e) {
      console.error('[ParallelWalkthrough] Failed to save visibility:', e);
    }
  });
}

function updateControlButtons(status = {}) {
  const running = !!status.running;
  const paused = !!status.paused;

  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');

  if (startBtn) startBtn.disabled = running;
  if (stopBtn) stopBtn.disabled = !running;

  if (pauseBtn) {
    pauseBtn.style.display = running && !paused ? 'inline-block' : 'none';
    pauseBtn.disabled = !running || paused;
  }
  if (resumeBtn) {
    resumeBtn.style.display = running && paused ? 'inline-block' : 'none';
    resumeBtn.disabled = !running || !paused;
  }
}

function getRunningStatusText(status = {}) {
  const {
    mode = 'sequential',
    paused,
    currentIndex = 0,
    total = 0,
    recoveryAttempts = 0,
    currentRetryCount = 0,
    options = {},
    parallelLaunched = 0,
    parallelCompleted = 0,
    parallelFailed = 0,
    parallelActive = 0,
  } = status;

  if (mode === 'parallel') {
    if (paused) {
      return `Paused launches - launched ${parallelLaunched}/${total}, active ${parallelActive}, done ${parallelCompleted}, failed ${parallelFailed}`;
    }
    return `Parallel running - launched ${parallelLaunched}/${total}, active ${parallelActive}, done ${parallelCompleted}, failed ${parallelFailed}`;
  }

  if (paused) {
    return `Paused at prompt ${currentIndex + 1} of ${total}`;
  }
  if (recoveryAttempts > 0) {
    return `Recovering... (attempt ${recoveryAttempts}/3) - Prompt ${currentIndex + 1} of ${total}`;
  }
  if (currentRetryCount > 0) {
    const maxRetries = Number(options?.maxRetriesPerPrompt || 0);
    return `Retrying prompt ${currentIndex + 1} of ${total} (${currentRetryCount}/${maxRetries || '?'})`;
  }
  return `Running prompt ${currentIndex + 1} of ${total}...`;
}

function getProgressPosition(status = {}) {
  if (status.mode === 'parallel') {
    const completed = Number(status.parallelCompleted || 0);
    const failed = Number(status.parallelFailed || 0);
    return completed + failed;
  }
  return Number(status.currentIndex || 0);
}

async function refreshStatus() {
  try {
    const res = await chrome.runtime.sendMessage({ type: 'AUTOMATION_STATUS_REQUEST' });
    if (res?.ok && res.status) {
      latestAutomationStatus = res.status;
      const { running, paused, total, currentIndex } = res.status;
      const progressPos = getProgressPosition(res.status);
      setProgress(running ? progressPos : total, total);
      setButtonsDisabled(running && !paused);
      updateControlButtons(res.status);
      if (running) {
        setStatus(getRunningStatusText(res.status), res.status.paused ? 'paused' : 'running');
      } else if (total > 0 && currentIndex >= total) {
        setStatus('Complete', 'idle');
      } else {
        setStatus('Idle', 'idle');
      }
    }
  } catch (e) {
    console.error('[RefreshStatus] Error:', e);
  }
}

initSettingsUI();

async function startAutomation() {
  try {
    // Check if automation is already running
    const statusRes = await chrome.runtime.sendMessage({ type: 'AUTOMATION_STATUS_REQUEST' });
    if (statusRes?.ok && statusRes.status?.running) {
      showToast('Automation is already running. Stop it first.', 'error');
      setStatus(getRunningStatusText(statusRes.status), statusRes.status.paused ? 'paused' : 'running');
      return;
    }

    const textarea = document.getElementById('prompts');
    const separatorInput = document.getElementById('separatorInput');
    const separator = resolveSeparator(separatorInput?.value);
    const appendText = document.getElementById('appendPromptText')?.value?.trim() || '';
    const prependText = document.getElementById('systemPrompt')?.value?.trim() || '';
    const launchPlan = buildPromptLaunchPlan(textarea.value, separator, appendText, prependText);
    const prompts = launchPlan.prompts;
    if (prompts.length === 0) {
      setStatus('Please enter at least one prompt.');
      return;
    }
    if (launchPlan.duplicateChanged > 0) {
      showToast(`Adjusted ${launchPlan.duplicateChanged} duplicate prompt(s) with typo-like variations`, 'info', 4000);
    }
    const tabId = await getActiveTabId();
    if (!tabId) {
      setStatus('No active tab found.');
      return;
    }
    setStatus('Starting...');
    hideError(); // Clear any previous error
    // Get current settings and include them in START_AUTOMATION to avoid race conditions
    const uiSettings = await saveSettingsFromUI();
    let currentSettings = { ...(uiSettings || {}) };
    if (!uiSettings) {
      const settingsRes = await chrome.runtime.sendMessage({ type: 'GET_SETTINGS' });
      currentSettings = { ...(settingsRes?.settings || {}) };
    }
    const parallelTabCount = launchPlan.hasTabMarkers ? launchPlan.tabPromptGroups.length : 0;
    if (launchPlan.hasTabMarkers) {
      showToast(`Detected ${parallelTabCount} tab group(s) using ${NEW_TAB_MARKER}`, 'info', 3000);
    }
    const res = await chrome.runtime.sendMessage({
      type: 'START_AUTOMATION',
      prompts,
      tabPromptGroups: launchPlan.hasTabMarkers ? launchPlan.tabPromptGroups : null,
      tabId,
      options: currentSettings,
    });
    if (res?.ok) {
      const initialStatus = launchPlan.hasTabMarkers
        ? { mode: 'parallel', running: true, paused: false, total: parallelTabCount, parallelLaunched: 0, parallelCompleted: 0, parallelFailed: 0, parallelActive: 0 }
        : { mode: 'sequential', running: true, paused: false, currentIndex: 0, total: prompts.length };
      setStatus(getRunningStatusText(initialStatus), 'running');
      setProgress(getProgressPosition(initialStatus), initialStatus.total);
      updateControlButtons({ running: true, paused: false });
      await chrome.runtime.sendMessage({
        type: 'SAVE_PROMPT_HISTORY',
        item: { prompts: launchPlan.promptsWithMarkers, settings: currentSettings },
      });
    } else {
      setStatus(`Failed to start: ${res?.error || 'Unknown error'}`, 'error');
      showToast(res?.error || 'Failed to start', 'error');
    }
  } catch (e) {
    console.error('[StartAutomation] Error:', e);
    setStatus(`Failed to start: ${e}`, 'error');
  }
}

document.getElementById('startBtn').addEventListener('click', startAutomation);

if (pauseBtn) {
  pauseBtn.addEventListener('click', async () => {
    try {
      const res = await chrome.runtime.sendMessage({ type: 'PAUSE_AUTOMATION' });
      if (res?.ok) {
        setStatus('Paused', 'paused');
        updateControlButtons({ running: true, paused: true });
      } else {
        showToast(res?.error || 'Failed to pause', 'error');
      }
    } catch (e) {
      console.error('[PauseBtn] Error:', e);
      showToast('Failed to pause', 'error');
    }
  });
}

if (resumeBtn) {
  resumeBtn.addEventListener('click', async () => {
    try {
      const res = await chrome.runtime.sendMessage({ type: 'RESUME_AUTOMATION' });
      if (res?.ok) {
        setStatus('Resuming...', 'running');
