      div.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          keyEventFired = true;
        }
      });
      
      document.body.appendChild(div);
      clickSend(null, div);
      
      expect(keyEventFired).toBe(true);
      document.body.removeChild(div);
    });
  });
});

